#include "tools/touplow"

#include <gtest/gtest.h>

namespace tools
{
//---------------------------------------------------------------------------//
TEST(Touplow, ToLowercaseBasic)
{
  std::string s = "ABC";
  tolowercase(s);
  EXPECT_EQ(s, "abc");
}

TEST(Touplow, ToLowercaseMixed)
{
  std::string s = "AbC123";
  tolowercase(s);
  EXPECT_EQ(s, "abc123");
}

TEST(Touplow, ToLowercaseAlreadyLower)
{
  std::string s = "xyz";
  tolowercase(s);
  EXPECT_EQ(s, "xyz");
}

TEST(Touplow, ToLowercaseEmpty)
{
  std::string s = "";
  tolowercase(s);
  EXPECT_EQ(s, "");
}

TEST(Touplow, ToLowercaseNonAscii)
{
  std::string s = "ÉCOLE";
  tolowercase(s);
  EXPECT_EQ(s, "École");  // Non-ASCII chars unchanged
}

TEST(Touplow, ToUppercaseBasic)
{
  std::string s = "abc";
  touppercase(s);
  EXPECT_EQ(s, "ABC");
}

TEST(Touplow, ToUppercaseMixed)
{
  std::string s = "aBc123";
  touppercase(s);
  EXPECT_EQ(s, "ABC123");
}

TEST(Touplow, ToUppercaseAlreadyUpper)
{
  std::string s = "XYZ";
  touppercase(s);
  EXPECT_EQ(s, "XYZ");
}

TEST(Touplow, ToUppercaseEmpty)
{
  std::string s = "";
  touppercase(s);
  EXPECT_EQ(s, "");
}

TEST(Touplow, ToUppercaseNonAscii)
{
  std::string s = "école";
  touppercase(s);
  EXPECT_EQ(s, "éCOLE");  // Non-ASCII chars unchanged
}

//---------------------------------------------------------------------------//
}  // namespace tools
